cat > /sandbox/primes.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define LIMIT 1000000
#define FIRST_N 30

int main(void) {
    bool *is_composite = calloc(LIMIT, sizeof(bool));
    if (is_composite == NULL) {
        fprintf(stderr, "allocation failed\n");
        return EXIT_FAILURE;
    }

    /* Sieve of Eratosthenes over [0, LIMIT) */
    is_composite[0] = true;
    is_composite[1] = true;
    for (long i = 2; i * i < LIMIT; i++) {
        if (!is_composite[i]) {
            for (long j = i * i; j < LIMIT; j += i) {
                is_composite[j] = true;
            }
        }
    }

    printf("First %d primes:\n", FIRST_N);
    int count = 0;
    for (long n = 2; count < FIRST_N; n++) {
        if (!is_composite[n]) {
            printf("%ld%s", n, (count + 1 < FIRST_N) ? " " : "\n");
            count++;
        }
    }

    unsigned long long sum = 0;
    for (long n = 2; n < LIMIT; n++) {
        if (!is_composite[n]) {
            sum += (unsigned long long)n;
        }
    }
    printf("Sum of primes below %d: %llu\n", LIMIT, sum);

    free(is_composite);
    return EXIT_SUCCESS;
}
EOF

